import outline from '../../data/pakistan-outline.json';

/**
 * Where a site falls on the static Pakistan outline.
 *
 * The outline is generated by `pipeline/gis/export_outline_svg.py`, and this is
 * the same arithmetic it used — equirectangular, x scaled by cos(refLat) — read
 * from the constants it wrote, so the dots and the provinces cannot drift
 * apart. `outlineProjection.test.ts` projects a known site and checks it lands
 * inside its province's bounding box.
 */
export interface OutlineDoc {
  viewBox: [number, number, number, number];
  projection: { refLat: number; scale: number; minX: number; maxLat: number };
  provinces: { name: string; code: string; d: string }[];
}

export const PAKISTAN_OUTLINE = outline as unknown as OutlineDoc;

export function projectToOutline(lat: number, lng: number): { x: number; y: number } {
  const { refLat, scale, minX, maxLat } = PAKISTAN_OUTLINE.projection;
  const kx = Math.cos((refLat * Math.PI) / 180);
  return { x: (lng * kx - minX) * scale, y: (maxLat - lat) * scale };
}
